  --spacing-224: 224px;

  /* ── LAYOUT ── */
  --page-max-width: 1200px;
  --section-gap: 80px;
  --card-padding: 32px;

  /* ── BORDER RADIUS ── */
  --radius-sm: 8px;
  --radius-nav: 14px;
  --radius-buttons: 14px;
  --radius-cards: 32px;
  --radius-images: 40px;
  --radius-badges: 1000px;
  --radius-orbs: 1600px;

  /* ── SURFACES ── */
  --surface-base: #ffffeb;
  --surface-nav: #ffffff;
  --surface-muted: #e4e4d0;
  --surface-accent: #f0d7ff;
  --surface-teal: #034f46;
  --surface-dark: #1a1a1a;
}

:root {
  --color-cream-paper: #ffffeb;
  --color-midnight-ink: #1a1a1a;
  --color-pure-black: #000000;
  --color-white: #ffffff;
  --color-stone-mist: #e4e4d0;
  --color-graphite-veil: #8a8a80;
  --color-smoke: #5f5f59;
  --color-charcoal: #222222;
  --color-charcoal-mist: #333333;
  --color-deep-forest-teal: #034f46;
  --color-lavender-whisper: #f0d7ff;
  --color-amber-pulse: #ffa946;
  --font-figtree: 'Figtree', ui-sans-serif, system-ui, sans-serif;
  --font-eb-garamond: 'EB Garamond', Georgia, serif;
  --text-display-xl: 120px;
  --leading-display-xl: 0.85;
  --tracking-display-xl: -0.13em;
  --text-display: 64px;
  --leading-display: 0.95;
  --tracking-display: -0.05em;
  --text-heading-lg: 48px;
  --leading-heading-lg: 0.95;
  --tracking-heading-lg: -0.07em;
  --text-heading: 32px;
  --leading-heading: 1;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1;
  --text-subheading: 20px;
  --leading-subheading: 1.3;
  --text-body: 16px;
  --leading-body: 1.3;
  --text-caption: 14px;
  --leading-caption: 1.3;
  --radius-nav: 14px;
  --radius-buttons: 14px;
  --radius-cards: 32px;
  --radius-images: 40px;
  --radius-badges: 1000px;
  --radius-orbs: 1600px;
  --page-max-width: 1200px;
}

/* ── BASE RESET ── */
body {
  background-color: var(--color-cream-paper);
  color: var(--color-midnight-ink);
  font-family: var(--font-figtree);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ── DISPLAY HEADLINES — EB GARAMOND ONLY ── */
/* Rule: EB Garamond ONLY at 32px and above. Never on body/UI text. */
h1 {
  font-family: var(--font-eb-garamond);
  font-size: clamp(64px, 9vw, 120px);
  font-weight: 400;
  line-height: var(--leading-display-xl);
  letter-spacing: var(--tracking-display-xl);
}

h2 {
  font-family: var(--font-eb-garamond);
  font-size: clamp(48px, 5vw, 64px);
  font-weight: 400;
  line-height: var(--leading-display);
  letter-spacing: var(--tracking-display);
}

h3 {
  font-family: var(--font-eb-garamond);
  font-size: 48px;
  font-weight: 400;
  line-height: var(--leading-heading-lg);
  letter-spacing: var(--tracking-heading-lg);
}

h4 {
  font-family: var(--font-figtree);
  font-size: var(--text-heading-sm);
  font-weight: 700;
  line-height: var(--leading-heading-sm);
}

h5, h6 {
  font-family: var(--font-figtree);
  font-size: var(--text-body);
  font-weight: 600;
}

p, span, li, a, label, input, textarea, select, button, td, th {
  font-family: var(--font-figtree);
}

/* ── TWO-TONE HEADLINE (Wispr Flow signature) ── */
.headline-two-tone .muted {
  color: var(--color-graphite-veil);
}
.headline-two-tone .strong {
  color: var(--color-midnight-ink);
}

/* ── DARK SECTION OVERRIDES ── */
.section-dark {
  background-color: var(--color-midnight-ink);
  color: var(--color-white);
}
.section-dark h1,
.section-dark h2,
.section-dark h3 {
  color: var(--color-white);
}
.section-dark p {
  color: rgba(255,255,255,0.7);
}

/* ── TEAL SECTION ── */
.section-teal {
  background-color: var(--color-deep-forest-teal);
  color: var(--color-white);
}

/* ── ANNOUNCEMENT BANNER ── */
.announcement-banner {
  background-color: var(--color-deep-forest-teal);
  color: var(--color-white);
  font-family: var(--font-figtree);
  font-size: 14px;
  font-weight: 500;
  padding: 10px 24px;
  text-align: center;
  width: 100%;
}

/* ── NAVIGATION BAR ── */
.nav-wispr {
  background: var(--color-white);
  border: 1px solid var(--color-stone-mist);
  border-radius: var(--radius-nav);
  padding: 8px 12px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}
.nav-link {
  font-family: var(--font-figtree);
  font-size: 14px;
  font-weight: 500;
  color: var(--color-midnight-ink);
  text-decoration: none;
  transition: opacity 0.2s ease;
}
.nav-link:hover { opacity: 0.65; }

/* ── PRIMARY CTA BUTTON — LAVENDER ── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background-color: var(--color-lavender-whisper);
  color: var(--color-midnight-ink);
  border: 1px solid var(--color-midnight-ink);
  border-radius: var(--radius-buttons);
  padding: 10px 18px;
  font-family: var(--font-figtree);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: letter-spacing 0.3s ease, opacity 0.2s ease;
  letter-spacing: 0;
  text-decoration: none;
}
.btn-primary:hover {
  letter-spacing: 0.02em;
  opacity: 0.9;
}
/* RULE: Only ONE lavender button per view. Never use lavender for backgrounds. */

/* ── SECONDARY GHOST BUTTON ── */
.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: transparent;
  color: var(--color-midnight-ink);
  border: 1px solid var(--color-midnight-ink);
  border-radius: var(--radius-buttons);
  padding: 10px 18px;
  font-family: var(--font-figtree);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
  text-decoration: none;
}
.btn-ghost:hover {
  background: var(--color-midnight-ink);
  color: var(--color-white);
}

/* Dark section ghost button */
.section-dark .btn-ghost {
  color: var(--color-white);
  border-color: var(--color-white);
}
.section-dark .btn-ghost:hover {
  background: var(--color-white);
  color: var(--color-midnight-ink);
}

/* ── PLATFORM PILL ── */
.btn-platform {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid var(--color-midnight-ink);
  border-radius: var(--radius-badges);
  padding: 8px 16px;
  font-family: var(--font-figtree);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}
.btn-platform:hover {
  background: var(--color-stone-mist);
}

/* ── FEATURE CARD ── */
.card-wispr {
  background: var(--color-cream-paper);
  border: 1px solid var(--color-stone-mist);
  border-radius: var(--radius-cards);
  padding: var(--card-padding);
  transition: border-color 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease;
}
.card-wispr:hover {
  border-color: var(--color-graphite-veil);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
}

/* ── BADGE / TAG ── */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: var(--radius-badges);
  padding: 6px 14px;
  font-family: var(--font-figtree);
  font-size: 12px;
  font-weight: 500;
}
.badge-teal {
  background: var(--color-deep-forest-teal);
  color: var(--color-white);
}
.badge-outline {
  border: 1px solid var(--color-midnight-ink);
  color: var(--color-midnight-ink);
}
.badge-amber {
  background: var(--color-amber-pulse);
  color: var(--color-midnight-ink);
}

/* ── UNDERLINE ACCENT (Lavender) ── */
.underline-accent {
  position: relative;
  display: inline-block;
}
.underline-accent::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 5px;
  background: var(--color-lavender-whisper);
  border-radius: 4px;
}

/* ── DECORATIVE ORB ── */
.orb {
  border-radius: var(--radius-orbs);
  background: var(--color-midnight-ink);
}
.orb-lavender {
  background: var(--color-lavender-whisper);
}

/* ── WORD REVEAL ANIMATION ── */
.word-reveal-container .word {
  opacity: 0.15;
  transition: opacity 0.4s ease;
  display: inline-block;
  margin-right: 0.25em;
}
.word-reveal-container .word.active {
  opacity: 1;
}

/* ── SECTION RHYTHM (cream → dark → cream → teal → cream) ── */
.section-light {
  background-color: var(--color-cream-paper);
  color: var(--color-midnight-ink);
  padding: var(--section-gap) 0;
}
.section-dark {
  background-color: var(--color-midnight-ink);
  color: var(--color-white);
  padding: var(--section-gap) 0;
}
.section-teal {
  background-color: var(--color-deep-forest-teal);
  color: var(--color-white);
  padding: 64px 0;
}

/* ── LAYOUT CONTAINER ── */
.container-wispr {
  max-width: var(--page-max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── SCROLLING MARQUEE ── */
@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
.marquee-track {
  display: flex;
  width: 200%;
  animation: marquee 25s linear infinite;
}
.marquee-track:hover {
  animation-play-state: paused;
}

/* ── SCAN LINE PROGRESS BAR ── */
.scan-line-bar {
  position: relative;
  height: 2px;
  background: var(--color-stone-mist);
  overflow: hidden;
}
.scan-line-bar::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: #3b82f6;
  animation: scanline 2s infinite cubic-bezier(0.8, 0, 0.2, 1);
}
@keyframes scanline {
  0% { left: -100%; }
  100% { left: 200%; }
}

/* ── WISPR FLOW ANIMATIONS ── */
/* Hero badge pulse dot */
@keyframes wispr-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.8); }
}
.pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-deep-forest-teal);
  animation: wispr-pulse 2s ease-in-out infinite;
  display: inline-block;
}

/* ── FAQ ACCORDION ── */
.faq-item {
  border-top: 1px solid var(--color-stone-mist);
}
.faq-item:last-child {
  border-bottom: 1px solid var(--color-stone-mist);
}
.faq-question {
  font-family: var(--font-figtree);
  font-size: 16px;
  font-weight: 600;
  color: var(--color-midnight-ink);
  cursor: pointer;
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.faq-answer {
  font-family: var(--font-figtree);
  font-size: 16px;
  color: var(--color-smoke);
  line-height: 1.6;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  max-height: 0;
  padding-bottom: 0;
}
.faq-item.open .faq-answer {
  max-height: 500px;
  padding-bottom: 20px;
}
.faq-toggle {
  color: var(--color-deep-forest-teal);
  font-size: 20px;
  font-weight: 400;
  transition: transform 0.3s ease;
  flex-shrink: 0;
}
.faq-item.open .faq-toggle {
  transform: rotate(45deg);
}

