9: function CountUp({ value, suffix = "", prefix = "", duration = 2 }: { value: number; suffix?: string; prefix?: string; duration?: number }) {
10:   const [count, setCount] = useState(0);
11:   const ref = useRef(null);
12:   const inView = useInView(ref, { once: true });
13:   useEffect(() => {
14:     if (!inView) return;
15:     let start = 0;
16:     const step = Math.max(Math.floor((duration * 1000) / value), 15);
17:     const timer = setInterval(() => {
18:       start += 1;
19:       if (start >= value) { setCount(value); clearInterval(timer); }
20:       else setCount(start);
21:     }, step);
22:     return () => clearInterval(timer);
23:   }, [inView, value, duration]);
24:   return <span ref={ref}>{prefix}{count}{suffix}</span>;
25: }
