import { ArrowRight, Star, ShieldCheck, Plug, Wrench, ChevronDown, ChevronUp } from "lucide-react";

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: [0.16, 1, 0.3, 1] as const } }
};

const products = [
  {
    id: "home-ev-charger",
    name: "Home EV Charger",
