            Now available
          </p>
          <h1 style={{ fontFamily: "var(--font-eb-garamond)", fontSize: "clamp(36px, 5vw, 64px)", fontWeight: 400, color: "#ffffff", letterSpacing: "-0.03em", lineHeight: 1 }}>
            {heroImages[heroSlide].label}
          </h1>
        </div>

        {/* Dots */}
        <div style={{ position: "absolute", bottom: "48px", right: "6%", display: "flex", gap: "8px", zIndex: 10 }}>
          {heroImages.map((_, i) => (
            <button
              key={i}
              onClick={() => setHeroSlide(i)}
              style={{
                width: i === heroSlide ? "28px" : "8px",
                height: "8px",
                borderRadius: "4px",
                background: i === heroSlide ? "#ffffff" : "rgba(255,255,255,0.4)",
                border: "none",
                cursor: "pointer",
                transition: "all 0.3s ease",
                padding: 0,
              }}
            />
          ))}
