import json
import time
from duckduckgo_search import DDGS

time.sleep(2) # avoid immediate rate limit
def search_images(query, max_results=3):
    try:
        with DDGS() as ddgs:
            results = ddgs.images(query, max_results=max_results)
            return results
    except Exception as e:
        return str(e)

print(json.dumps({
    "portable": search_images("portable ev charger 3.3kw cable type 2 product -statiq")
}, indent=2))

