"use client";

import React from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils"; // Assuming a utility exists or I'll implement standard class joining

type ButtonVariant = "primary" | "ghost" | "outline" | "custom";

interface AnimatedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  href?: string;
  variant?: ButtonVariant;
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  target?: string;
  rel?: string;
  onMouseEnter?: React.MouseEventHandler<HTMLButtonElement | HTMLAnchorElement>;
  onMouseLeave?: React.MouseEventHandler<HTMLButtonElement | HTMLAnchorElement>;
}

export default function AnimatedButton({
  href,
  variant = "primary",
  children,
  className = "",
  style,
  target,
  rel,
  onMouseEnter,
  onMouseLeave,
  ...props
}: AnimatedButtonProps) {
  const baseClass = variant === "primary" 
    ? "btn-primary" 
    : variant === "ghost" 
      ? "btn-ghost" 
      : variant === "custom" ? "" : "";

  // The custom sliding effect CSS
  const buttonStyle: React.CSSProperties = {
    overflow: "hidden",
    position: "relative",
    cursor: "pointer",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    ...style,
  };

  const textWrapStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    transition: "transform 0.35s cubic-bezier(0.65, 0, 0.35, 1)",
    position: "relative",
    height: "1em", // Match text height
  };

  const spanStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    gap: "6px",
    height: "100%",
  };

  const content = (
    <span
      className="btn-text-wrap"
      style={textWrapStyle}
      // Hover handled via CSS in a style tag to apply globally easily, or inline via groups
    >
      <span className="btn-text-original" style={spanStyle}>
        {children}
      </span>
      <span className="btn-text-duplicate" style={{ ...spanStyle, position: "absolute", top: "100%", left: 0, width: "100%", justifyContent: "inherit" }}>
        {children}
      </span>
    </span>
  );

  const css = `
    .animated-btn-hover:hover .btn-text-wrap {
      transform: translateY(-100%);
    }
  `;

  if (href) {
    // If it's an external link
    if (href.startsWith("http") || href.startsWith("mailto") || href.startsWith("tel")) {
      return (
        <>
          <style>{css}</style>
          <a
            href={href}
            className={`animated-btn-hover ${baseClass} ${className}`.trim()}
            style={buttonStyle}
            target={target}
            rel={rel}
            onMouseEnter={onMouseEnter as React.MouseEventHandler<HTMLAnchorElement>}
            onMouseLeave={onMouseLeave as React.MouseEventHandler<HTMLAnchorElement>}
          >
            {content}
          </a>
        </>
      );
    }
    return (
      <>
        <style>{css}</style>
        <Link
          href={href}
          className={`animated-btn-hover ${baseClass} ${className}`.trim()}
          style={buttonStyle}
          target={target}
          onMouseEnter={onMouseEnter as React.MouseEventHandler<HTMLAnchorElement>}
          onMouseLeave={onMouseLeave as React.MouseEventHandler<HTMLAnchorElement>}
        >
          {content}
        </Link>
      </>
    );
  }

  return (
    <>
      <style>{css}</style>
      <button
        className={`animated-btn-hover ${baseClass} ${className}`.trim()}
        style={buttonStyle}
        onMouseEnter={onMouseEnter as React.MouseEventHandler<HTMLButtonElement>}
        onMouseLeave={onMouseLeave as React.MouseEventHandler<HTMLButtonElement>}
        {...props}
      >
        {content}
      </button>
    </>
  );
}

