"use client";

import React, { useRef } from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import AnimatedButton from "./AnimatedButton";
import { Home, Zap, MapPin } from "lucide-react";

interface CardData {
  title: string;
  description: string;
  ctaText: string;
  ctaHref: string;
  icon: React.ReactNode;
  bgGradient: string;
}

const cards: CardData[] = [
  {
    title: "Home Charging",
    description: "Nectar home EV chargers 7.4kW, 11kW, 22kW. Portable 3.3kW & 7.4kW. Safe overnight charging.",
    ctaText: "View AC Chargers",
    ctaHref: "/shop",
    icon: <Home size={32} color="var(--color-midnight-ink)" />,
    bgGradient: "linear-gradient(135deg, #f8f8f5 0%, #e4e4d0 100%)"
  },
  {
    title: "DC Fast Charging",
    description: "Configurable DC Fast Chargers 60kW to 360kW. Built for highways, commercial hubs, and fleets.",
    ctaText: "View DC Chargers",
    ctaHref: "#",
    icon: <Zap size={32} color="#ffffff" />,
    bgGradient: "linear-gradient(135deg, var(--color-midnight-ink) 0%, var(--color-charcoal) 100%)"
  },
  {
    title: "Public Network",
    description: "Find chargers instantly via app. Live status, one-tap start, seamless payment. 1,014+ cities.",
    ctaText: "Explore EVLinq",
    ctaHref: "#",
    icon: <MapPin size={32} color="var(--color-midnight-ink)" />,
    bgGradient: "linear-gradient(135deg, #f0d7ff 0%, #e0c2f5 100%)"
  }
];

function ThreeDCard({ data, index }: { data: CardData; index: number }) {
  const ref = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  // Smooth out the rotation
  const mouseXSpring = useSpring(x, { stiffness: 150, damping: 20 });
  const mouseYSpring = useSpring(y, { stiffness: 150, damping: 20 });

  // Map mouse position to rotation (-15 to 15 degrees)
  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["12deg", "-12deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-12deg", "12deg"]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Normalize to -0.5 to 0.5
    const xPct = mouseX / width - 0.5;
    const yPct = mouseY / height - 0.5;

    x.set(xPct);
    y.set(yPct);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  const isDark = index === 1;

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        rotateX,
        rotateY,
        transformStyle: "preserve-3d",
      }}
      className="relative w-full aspect-[4/5] rounded-[32px] p-8 flex flex-col justify-between cursor-pointer"
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-50px" }}
      transition={{ duration: 0.6, delay: index * 0.15, ease: [0.16, 1, 0.3, 1] }}
    >
      {/* Background with shadow */}
      <div 
        className="absolute inset-0 rounded-[32px] shadow-2xl transition-shadow duration-300 pointer-events-none"
        style={{ 
          background: data.bgGradient,
          boxShadow: "0 24px 48px rgba(0,0,0,0.12), inset 0 2px 0 rgba(255,255,255,0.4)",
          transform: "translateZ(-30px)" 
        }}
      />

      {/* Content Layer (pops out) */}
      <div 
        className="relative z-10 flex flex-col h-full justify-between" 
        style={{ transform: "translateZ(40px)" }} // The Parallax Pop
      >
        <div>
          <div 
            className="w-16 h-16 rounded-full flex items-center justify-center mb-6"
            style={{ 
              background: isDark ? "rgba(255,255,255,0.1)" : "rgba(255,255,255,0.5)",
              backdropFilter: "blur(10px)",
              transform: "translateZ(20px)" 
            }}
          >
            {data.icon}
          </div>

          <h3 
            style={{ 
              fontFamily: "var(--font-eb-garamond)", 
              fontSize: "36px", 
              lineHeight: 1.1,
              letterSpacing: "-0.02em",
              color: isDark ? "#fff" : "var(--color-midnight-ink)",
              marginBottom: "16px",
              transform: "translateZ(30px)"
            }}
          >
            {data.title}
          </h3>

          <p 
            style={{ 
              fontFamily: "var(--font-figtree)",
              fontSize: "15px",
              lineHeight: 1.6,
              color: isDark ? "rgba(255,255,255,0.7)" : "var(--color-smoke)",
              transform: "translateZ(20px)"
            }}
          >
            {data.description}
          </p>
        </div>

        <div style={{ transform: "translateZ(50px)" }}>
          <AnimatedButton 
            href={data.ctaHref} 
            variant={isDark ? "custom" : "ghost"}
            className={isDark ? "btn-primary" : ""}
            style={isDark ? {
              background: "#fff",
              color: "var(--color-midnight-ink)",
              borderColor: "#fff"
            } : {
              background: "rgba(255,255,255,0.5)",
              borderColor: "var(--color-stone-mist)"
            }}
          >
            {data.ctaText}
          </AnimatedButton>
        </div>
      </div>
    </motion.div>
  );
}

export default function ThreeDCardsSection() {
  return (
    <section className="py-32 bg-[var(--color-cream-paper)] relative overflow-hidden" style={{ perspective: "1500px" }}>
      <div className="container-wispr mx-auto px-6">
        <div className="text-center mb-20">
          <motion.p 
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-[12px] font-bold tracking-widest uppercase text-[var(--color-graphite-veil)] mb-3"
            style={{ fontFamily: "var(--font-figtree)" }}
          >
