          <motion.h2 
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.1 }}
            className="text-4xl md:text-5xl lg:text-6xl text-[var(--color-midnight-ink)] font-normal tracking-tight"
            style={{ fontFamily: "var(--font-eb-garamond)" }}
          >
            Powering the future of <em>mobility</em>
          </motion.h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl mx-auto">
          {cards.map((card, idx) => (
            <ThreeDCard key={card.title} data={card} index={idx} />
          ))}
        </div>
      </div>
    </section>
  );
}

