17: function CountUp({ value, suffix = "", prefix = "", duration = 2 }: { value: number; suffix?: string; prefix?: string; duration?: number }) {
18:   const [count, setCount] = useState(0);
19:   const ref = useRef(null);
20:   const inView = useInView(ref, { once: true });
21:   useEffect(() => {
22:     if (!inView) return;
23:     let start = 0;
24:     const step = Math.max(Math.floor((duration * 1000) / value), 15);
25:     const timer = setInterval(() => {
26:       start += 1;
27:       if (start >= value) { setCount(value); clearInterval(timer); }
28:       else setCount(start);
29:     }, step);
30:     return () => clearInterval(timer);
31:   }, [inView, value, duration]);
32:   return <span ref={ref}>{prefix}{count}{suffix}</span>;
33: }
