const [scrollContainer, setScrollContainer] = useState<React.RefObject<HTMLElement | null> | undefined>();
const [isMobile, setIsMobile] = useState(false);

useEffect(() => {
  if (externalContainerRef?.current) {
    setScrollContainer(externalContainerRef);
  }
  const media = window.matchMedia("(max-width: 768px)");
  setIsMobile(media.matches);
  const listener = () => setIsMobile(media.matches);
  media.addEventListener("change", listener);
  return () => media.removeEventListener("change", listener);
}, [externalContainerRef]);

const { scrollYProgress } = useScroll({
  target: containerRef,
  ...(scrollContainer ? { container: scrollContainer } : {}),
  offset: ["start start", "end end"],
});

// Responsive values to prevent 3D rotation overlap on mobile while staying in viewport
const targetScale = isMobile ? 0.75 : 0.9;
const targetLeftX = isMobile ? "-35%" : "-15%";
const targetRightX = isMobile ? "35%" : "15%";
const targetLeftMidX = isMobile ? "-17.5%" : "-7.5%";
const targetRightMidX = isMobile ? "17.5%" : "7.5%";

// Stage 1 to 2: Separation (0 to 0.4), then Stage 2 to 3: Overlap closer (0.4 to 0.8)
const leftX = useTransform(scrollYProgress, [0, 0.4, 0.8], ["0%", targetLeftX, targetLeftMidX]);
const rightX = useTransform(scrollYProgress, [0, 0.4, 0.8], ["0%", targetRightX, targetRightMidX]);

const scale = useTransform(scrollYProgress, [0, 0.4], [1, targetScale]);

