22: /* ── COUNT UP ── */
23: function CountUp({ value, suffix = "", prefix = "", duration = 2 }: { value: number; suffix?: string; prefix?: string; duration?: number }) {
24:   const [count, setCount] = useState(0);
25:   const ref = useRef(null);
26:   const inView = useInView(ref, { once: true });
27:   useEffect(() => {
28:     if (!inView) return;
29:     let start = 0;
30:     const step = Math.max(Math.floor((duration * 1000) / value), 15);
31:     const timer = setInterval(() => {
32:       start += 1;
33:       if (start >= value) { setCount(value); clearInterval(timer); }
34:       else setCount(start);
35:     }, step);
36:     return () => clearInterval(timer);
37:   }, [inView, value, duration]);
38:   return <span ref={ref}>{prefix}{count}{suffix}</span>;
39: }
40: 
41: /* ── WORD REVEAL ── */
42: function WordReveal({ text, className = "" }: { text: string; className?: string }) {
43:   const ref = useRef<HTMLDivElement>(null);
44:   const [activeIndex, setActiveIndex] = useState(-1);
45:   const words = text.split(" ");
46: 
47:   useEffect(() => {
48:     const el = ref.current;
49:     if (!el) return;
50:     const observer = new IntersectionObserver(([entry]) => {
51:       if (entry.isIntersecting) {
52:         words.forEach((_, i) => {
53:           setTimeout(() => setActiveIndex(i), i * 80);
54:         });
55:       }
56:     }, { threshold: 0.3 });
57:     observer.observe(el);
58:     return () => observer.disconnect();
59:   }, [words.length]);
60: 
61:   return (
62:     <div ref={ref} className={`word-reveal-container ${className}`}>
63:       {words.map((word, i) => (
64:         <span key={i} className={`word ${i <= activeIndex ? 'active' : ''}`}>
65:           {word}
66:         </span>
67:       ))}
68:     </div>
69:   );
70: }
