10: export function SmoothScrollProvider({ children }: { children: ReactNode }) {
11:   useEffect(() => {
12:     // Disable Lenis on touch devices to allow native, hardware-accelerated scrolling for GSAP
13:     const isTouch = window.matchMedia("(pointer: coarse)").matches;
14:     if (isTouch) return;
15: 
16:     const lenis = new Lenis({
17:       duration: 1.2,
18:       easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
19:       smoothWheel: true,
20:       wheelMultiplier: 1,
21:     });
22: 
23:     // Sync Lenis scroll position with GSAP ScrollTrigger
24:     lenis.on("scroll", ScrollTrigger.update);
25: 
26:     // Tick Lenis inside GSAP ticker for frame-perfect sync
27:     gsap.ticker.add((time) => {
28:       lenis.raf(time * 1000);
29:     });
30: 
31:     // Disable GSAP's default lag smoothing to avoid conflicts
32:     gsap.ticker.lagSmoothing(0);
33: 
34:     return () => {
35:       lenis.destroy();
36:       gsap.ticker.remove((time) => {
37:         lenis.raf(time * 1000);
38:       });
39:     };
40:   }, []);
41: 
42:   return <div suppressHydrationWarning>{children}</div>;
43: }
